-- US admission requirements, retry of schools that failed in waves 2 and 3 (checked 13 Nov 2026). Needs step181.
update schools set admission_info = $q${"ug": "Needs a 2.5 unweighted high school GPA, plus a 3.0 GPA or minimum ACT/SAT scores in English and math (ACT English 18, ACT Math 19, SAT reading and writing 500, SAT Math 510). Official proof of English is also required. Students who do not meet this can only be considered by committee, by invitation.", "pg": "Official transcripts and individual mark sheets are required, with attested copies and a certified English translation if not in English. The Graduate School offers free foreign transcript evaluation. General Graduate School requirements also apply.", "english": "Graduate: TOEFL iBT 79, IELTS 6.5, PTE Academic 53, Duolingo 110, TOEFL Essentials 8.5. Scores are valid for two years. Undergraduate applicants can use TOEFL, IELTS, PTE or Duolingo, but the undergraduate page does not state the minimum scores.", "how_to_apply": "Apply online through the university application portal, pay the fee, and send the forms and documents. Test scores go through the testing service (institution code 6672). Transcripts can be sent by mail or to admissions@louisiana.edu.", "deadlines": "Undergraduate: Fall June 1, Spring October 1, Summer March 1. Graduate: Fall May 15, Spring October 1, no summer start for international students.", "application_fee": "Undergraduate: $25 (non-refundable). Graduate fee is not stated on the page.", "documents": "Chronological Record of Education form, Confidential Financial Guarantee form with a current bank statement, passport copy, immunization form (TB, MMR, Td), and official or certified secondary and college transcripts with English translation.", "fees_link": "https://louisiana.edu/admissions-aid/costs-financial-aid", "sources": ["https://louisiana.edu/admissions/international-students", "https://louisiana.edu/graduateschool/admissions/international-applicants", "https://louisiana.edu/node/130876", "https://louisiana.edu/scholarship/international"]}$q$::jsonb, admission_link = $q$https://louisiana.edu/admissions-aid/costs-financial-aid$q$, admission_checked = '2026-11-13' where id = '14d526b5-12d1-42f0-8d60-033d367078ca' and country = 'United States';
update schools set admission_info = $q${"ug": "Minimum GPA depends on the program. Official original transcripts from every school attended are needed, in the original language and in English.", "pg": "Minimum GPA depends on the program. Most programs ask for a resume, personal statement and three recommendation letters, and some ask for GRE. Official transcripts from every school and college are needed.", "english": "Undergraduate: TOEFL iBT 79, IELTS 6.5, Duolingo 105, PTE 50, SAT reading and writing 510, ACT reading 19, or ELS level 112. Graduate: TOEFL iBT 80, IELTS 6.5, Duolingo 105, PTE 54. SAT, ACT and ELS are not accepted for graduate.", "how_to_apply": "Start the online application, create an account, and choose the category International - All Degree Levels.", "deadlines": "Fall June 15, Spring October 15, Summer February 15. Late applications may still be considered, so contact the Office of International Education.", "application_fee": "Not stated on the official page.", "documents": "Passport identification page (and for dependents), proof of funds (the undergraduate page states $29,800), a Sponsor Statement if the sponsor is not the student, and official transcripts.", "fees_link": "https://www.ferris.edu/international/admissions/undergraduate/requirements.htm", "sources": ["https://ferris.edu/international/admissions/undergraduate/requirements.htm", "https://www.ferris.edu/international/admissions/graduate/requirements.htm", "https://www.ferris.edu/international/admissions/englishpolicies.htm"]}$q$::jsonb, admission_link = $q$https://www.ferris.edu/international/admissions/undergraduate/requirements.htm$q$, admission_checked = '2026-11-13' where id = 'b3517ea8-0620-4651-9368-46b454c0a5b2' and country = 'United States';
update schools set admission_info = $q${"ug": "Secondary school marks in the original language with certified English translation are needed. Transfer applicants also send transcripts from every college attended.", "pg": "Apply through the Brooklyn College graduate application. Requirements differ by program, so check the program page.", "english": "The college FAQ asks for a TOEFL score (500 paper-based or 173 computer-based) if your first language is not English. This looks like an older format, so confirm the current minimum with admissions.", "how_to_apply": "Undergraduates register through welcome.brooklyn.edu. Graduates apply at welcome.brooklyn.edu/apply. International applicants educated abroad apply through UAPC. After admission, F-1 students complete the I-20 application in the F-1 International Student Portal.", "deadlines": "Not stated on the pages checked. Apply as early as possible and check the requirements and deadlines page.", "application_fee": "$65, paid to UAPC, for international applicants educated abroad (from the college FAQ).", "documents": "Official high school transcript with word-for-word English translation if needed, copies of mark sheets or exam certificates, and the I-20 application after admission.", "fees_link": "https://www.brooklyn.edu/bursar/tuition-and-fees/", "sources": ["https://www.brooklyn.edu/admissions-aid/international/how-to-apply/", "https://www.brooklyn.edu/admissions-aid/international/incoming-students/", "https://www.brooklyn.edu/admissions-aid/first-year/faq/"]}$q$::jsonb, admission_link = $q$https://www.brooklyn.edu/bursar/tuition-and-fees/$q$, admission_checked = '2026-11-13' where id = '4b3167fd-5eeb-4122-aebf-6ff3230f5ae0' and country = 'United States';
update schools set admission_info = $q${"ug": "First-year applicants send the online application with an essay and short answers, plus official secondary school transcripts sent directly from the school with a certified English translation.", "pg": "International transcripts can be unofficial at application, in English or certified translation. Admitted students must get a course-by-course evaluation from a NACES member company sent to the Graduate School.", "english": "Undergraduate: TOEFL 71 (or 4.0 on the new scale), IELTS 6.0, Duolingo 105, Pearson 54, iTEP Academic 3.7. Graduate: Duolingo 115, IELTS 6.5, TOEFL iBT 79 (or 4.5 on the new scale for tests taken from January 21, 2026). Waivers exist, so confirm with admissions.", "how_to_apply": "Apply online. For F-1 sponsorship you must show enough funds after admission. Graduate applicants also submit the International Transcript Evaluation Request after applying.", "deadlines": "Undergraduate: Fall April 1, Spring October 1, reviewed on a rolling basis. Graduate deadlines are on the Key Dates page and are not stated here.", "application_fee": "Undergraduate: $80 (non-refundable, paid by check or money order from a U.S. bank). Graduate fee is not stated.", "documents": "Official secondary transcripts (sent by the school, with certified translation), English score if not waived, and proof of funds for F-1 sponsorship after admission.", "fees_link": "https://www.uncw.edu/seahawk-life/support-success/international/students-scholars/resources/financial-resources", "sources": ["https://www.uncw.edu/seahawk-life/support-success/international/students-scholars/prospective-students/international", "https://uncw.edu/admissions/graduate/int-graduate", "https://www.uncw.edu/seahawk-life/support-success/international/students-scholars/resources/financial-resources"]}$q$::jsonb, admission_link = $q$https://www.uncw.edu/seahawk-life/support-success/international/students-scholars/resources/financial-resources$q$, admission_checked = '2026-11-13' where id = '15015008-7f10-4a28-8ce3-2195987a5d35' and country = 'United States';
update schools set admission_info = $q${"ug": "From the Ohio University international undergraduate page: above-average secondary grades are needed. Cambridge applicants generally need at least 6 passes at grade C or higher. SAT or ACT is optional. The page is written for Ohio University in general, so confirm Eastern Campus details with the campus.", "pg": "Not stated for this campus on the pages checked.", "english": "Undergraduate: TOEFL iBT 72 (writing 17), IELTS 6.0 (no band below 5.5), Duolingo 110, PTE 48, SAT 1060 or ACT 21. Applicants from listed countries, including Ghana, do not need to submit scores unless asked.", "how_to_apply": "Complete the Common App or the Ohio University online application, pay the fee, send school records and English proof. Eastern Campus admissions: (740) 695-1720.", "deadlines": "Fall: early action November 15, rolling February 1. Spring: November 1. Merit scholarships are only for fall starts.", "application_fee": "$75 for international applicants. A fee waiver can be requested from admissions.", "documents": "Academic records from every secondary school with certified English translation, English proof (unless exempt), and optional SAT/ACT, essays and recommendations.", "fees_link": "https://www.ohio.edu/admissions/international/costs-aid", "sources": ["https://www.ohio.edu/admissions/international/apply", "https://www.ohio.edu/admissions/international/dates-deadlines", "https://www.ohio.edu/eastern/admissions"]}$q$::jsonb, admission_link = $q$https://www.ohio.edu/admissions/international/costs-aid$q$, admission_checked = '2026-11-13' where id = '46e1123b-368c-45bd-a35c-f8b73053a543' and country = 'United States';
update schools set admission_info = $q${"ug": "From the Ohio University international undergraduate page: above-average secondary grades are needed. Cambridge applicants generally need at least 6 passes at grade C or higher. SAT or ACT is optional. The page is written for Ohio University in general, so confirm Lancaster Campus details with the campus.", "pg": "Not stated for this campus on the pages checked.", "english": "Undergraduate: TOEFL iBT 72 (writing 17), IELTS 6.0 (no band below 5.5), Duolingo 110, PTE 48, SAT 1060 or ACT 21. Applicants from listed countries, including Ghana, do not need to submit scores unless asked.", "how_to_apply": "Complete the Common App or the Ohio University online application, pay the fee, send school records and English proof. Lancaster Campus: (740) 654-6711.", "deadlines": "Fall: early action November 15, rolling February 1. Spring: November 1. Merit scholarships are only for fall starts.", "application_fee": "$75 for international applicants. A fee waiver can be requested from admissions.", "documents": "Academic records from every secondary school with certified English translation, English proof (unless exempt), and optional SAT/ACT, essays and recommendations.", "fees_link": "https://www.ohio.edu/admissions/international/costs-aid", "sources": ["https://www.ohio.edu/admissions/international/apply", "https://www.ohio.edu/admissions/international/dates-deadlines", "https://www.ohio.edu/lancaster/admissions/financial-aid-scholarships"]}$q$::jsonb, admission_link = $q$https://www.ohio.edu/admissions/international/costs-aid$q$, admission_checked = '2026-11-13' where id = '0c46aa9e-322e-4e81-aa82-4fa985c79f55' and country = 'United States';
update schools set admission_info = $q${"ug": "First-year applicants send official high school transcripts directly to the college (original language, with school stamp) and a certified word-for-word English translation if not in English.", "pg": "Non-U.S. transcripts need an official transcript plus a credential evaluation showing degree equivalency and grades on a 4.0 scale.", "english": "Undergraduate (one of): Duolingo 105, TOEFL iBT 80, IELTS 6.5, iTEP Academic Plus 3.8, SAT reading and writing 500, ACT reading 18 and English 20. Graduate: IELTS 6.5, TOEFL 83 (computer) or 550 (paper), Duolingo 105. Waivers may apply, so email international@charleston.edu.", "how_to_apply": "Apply through the same online application as domestic students. Admitted graduate students email the school for the Certificate of Finance form needed for the visa.", "deadlines": "Fall 2027 first-year: Early Action and Early Decision 1 November 2, Early Decision 2 and Regular Decision January 15. Spring 2027: November 2. Graduate deadlines are on the separate deadlines page.", "application_fee": "Not stated on the pages checked.", "documents": "High school transcripts with translation, one English score, passport photo page copy, and proof of financial support. Graduate: credential evaluation of foreign transcripts.", "fees_link": "https://charleston.edu/admission/apply/international/index.php", "sources": ["https://charleston.edu/admission/apply/international/application-checklists/freshman.php", "https://charleston.edu/grad-school/admissions/international-students.php"]}$q$::jsonb, admission_link = $q$https://charleston.edu/admission/apply/international/index.php$q$, admission_checked = '2026-11-13' where id = '973bd6eb-1558-4ceb-bbea-57c6db8af37f' and country = 'United States';
update schools set admission_info = $q${"ug": "Complete an accredited high school program. Top 25 percent of the class is admitted automatically, otherwise a 2.75 GPA is needed. Non-U.S. transcripts need a course-by-course evaluation with a GPA from an accepted agency. Transfer students need 30 or more college hours and a 2.0 GPA.", "pg": "Official transcripts with a course-by-course evaluation from a NACES member service (some MS engineering and computer science programs waive this). Some programs also ask for recommendation letters, resume, statement of purpose or portfolio.", "english": "Undergraduate: TOEFL 79, IELTS 6.5, Pearson 53 or Duolingo 105. Graduate: TOEFL iBT 79, IELTS 6.5 (6.0 in each section), PTE 53 or Duolingo 105; psychology and counseling need higher scores. Applicants from or with degrees from listed countries, including Ghana, are exempt. The page may be dated, so confirm with admissions.", "how_to_apply": "Undergraduates use the International Undergraduate Freshman or Transfer application on ApplyTexas. Graduate applicants apply at uttyler.edu/apply. Contact internationaladmissions@uttyler.edu.", "deadlines": "Undergraduate, applying from outside the U.S.: Fall May 31, Spring October 31, Summer February 28. Graduate deadlines vary by program.", "application_fee": "$75, non-refundable, for undergraduate and graduate.", "documents": "Official transcripts with course-by-course evaluation, English proof unless exempt, and program documents for graduate applicants.", "fees_link": "https://www.uttyler.edu/admissions-aid/tuition-financial-aid-fees/international-students/index.php", "sources": ["https://www.uttyler.edu/admissions/international/", "https://www.uttyler.edu/admissions-aid/tuition-financial-aid-fees/international-students/index.php"]}$q$::jsonb, admission_link = $q$https://www.uttyler.edu/admissions-aid/tuition-financial-aid-fees/international-students/index.php$q$, admission_checked = '2026-11-13' where id = 'eb011fdf-f32a-42a5-bd0d-72e9ea656db7' and country = 'United States';
update schools set admission_info = $q${"ug": "First-year applicants send transcripts from all secondary schools (with official translation if not in English), official SAT or ACT results, a passport copy, an immunization form or waiver, and financial support documents. If the SAT/ACT Reading score is below the minimum, TOEFL or IELTS is required. Transfers from outside the US need a course-by-course evaluation from a NACES member and TOEFL or IELTS, and those with fewer than 24 credits follow the first-year rules.", "pg": "You need a bachelor's degree or the foreign equivalent. GPA must meet one of these: 2.5 overall, 2.75 on the last 60 undergraduate hours, or 3.0 on at least nine graduate hours. GRE and GMAT are not required for most programs. Non-US transcripts must be evaluated by a NACES agency, and many programs ask for a statement of purpose and recommendation letters.", "english": "TOEFL or IELTS is needed when the SAT/ACT Reading score does not meet the minimum, and for transfers from non-US schools. Exact minimum scores are not listed on the pages I could read. Students who do not meet the English requirement may be admitted conditionally and take the Intensive English Language Program.", "how_to_apply": "Complete the online application, then email transcripts to transcripts@uno.edu or mail them to International Admissions and Recruitment, 2000 Lakeshore Drive, New Orleans, LA 70148. The official site now redirects to lsuneworleans.edu, which is the same university under its new name.", "deadlines": "For fall scholarship consideration, be admitted by January 15 with official transcripts and test results. No general international deadline is listed.", "documents": "Passport copy, transcripts, SAT/ACT or TOEFL/IELTS results, immunization form or waiver, financial support documents. The I-20 is not processed until financial documents arrive.", "fees_link": "https://www.uno.edu/admissions/apply-international-student/international-checklist", "sources": ["https://uno.edu/admissions/apply-international-student/international-checklist", "https://www.uno.edu/academics/grad/admission-requirements"]}$q$::jsonb, admission_link = $q$https://www.uno.edu/admissions/apply-international-student/international-checklist$q$, admission_checked = '2026-11-13' where id = '21615328-0cab-4e40-9640-79e1d731ce8f' and country = 'United States';
update schools set admission_info = $q${"ug": "SAT or ACT scores are optional for first-year international students, but scores can help you qualify for ASU Distinguished Scholarships. Transfer students may be exempt from the SAT/ACT requirement, and the Center for International Studies decides who qualifies.", "english": "Minimum English scores are on a separate English Language Proficiency page that I could not confirm. The ASU institution code for TOEFL and SAT is 6644.", "how_to_apply": "Apply to ASU and send documents to the Center for International Studies at cis@angelo.edu. Phone 325-942-2083.", "documents": "Send official SAT/ACT and TOEFL results by mail to Angelo State University, Center for International Studies, ASU Station #11035, San Angelo, TX 76909-1035. The page says to take the exam at least eight weeks before the application deadline.", "fees_link": "https://www.angelo.edu/life-on-campus/explore/center-for-international-studies/apply/paying-your-tuition.php", "sources": ["https://www.angelo.edu/dept/international-students/sat-or-act-exam.php"]}$q$::jsonb, admission_link = $q$https://www.angelo.edu/life-on-campus/explore/center-for-international-studies/apply/paying-your-tuition.php$q$, admission_checked = '2026-11-13' where id = '131e1da6-af86-45ee-beef-6b54ba330103' and country = 'United States';
update schools set admission_info = $q${"ug": "You need a copy of your valid passport, your original or attested high school diploma, and an official transcript from each high school or college you attended. SAT is strongly encouraged. Applicants without test scores may have to take the on-campus ACT Residual exam.", "pg": "You need a four-year bachelor's degree or the foreign equivalent. GPA must be at least 2.70 for all undergraduate work, or 3.00 for the last two years. Foreign transcripts need a course-by-course evaluation from WES, Josef Silny, ECE or International Education Evaluation. Some programs also ask for GRE or GMAT.", "english": "Undergraduate: TOEFL 61, IELTS 5.5 or Duolingo 85. Graduate: TOEFL iBT 79, IELTS 6.0 or Duolingo 100 (MS Computer Science: TOEFL 83, IELTS 6.5, Duolingo 107). Scores must be less than two years old. Waivers exist for some applicants.", "how_to_apply": "Apply online at utc.edu/apply, pay the fee, then send documents. Graduate documents must be sealed and stamped by the issuing school and mailed to Credential Evaluation Services, International Graduate Admissions, Center for Global Education, Dept. 4755, 615 McCallie Avenue, Chattanooga, TN 37403.", "deadlines": "Fall July 1. Spring November 1.", "application_fee": "$30 for undergraduate and $40 for graduate, non-refundable.", "documents": "Passport copy, transcripts and degree certificates, proof of funds for nine months of study before the I-20 is issued. Graduate applicants also need a degree certificate and full transcripts with all grades, and notary or professor attestation is not accepted.", "fees_link": "https://www.utc.edu/academic-affairs/center-for-global-education/international-student-and-scholar-services/prospective-students", "sources": ["https://www.utc.edu/academic-affairs/center-for-global-education/international-student-and-scholar-services/prospective-students", "https://www.utc.edu/academic-affairs/center-for-global-education/international-student-and-scholar-services/prospective-students/graduate-academic-doc-reqs", "https://www.utc.edu/research/graduate-school/prospective-students/graduate-school-admissions"]}$q$::jsonb, admission_link = $q$https://www.utc.edu/academic-affairs/center-for-global-education/international-student-and-scholar-services/prospective-students$q$, admission_checked = '2026-11-13' where id = '433833ae-ecab-44a2-889c-a95d2ef125b8' and country = 'United States';
update schools set admission_info = $q${"ug": "Send the application with essay, official transcripts from your school, English test results, and an Affidavit of Financial Support with a bank statement in US dollars dated within 6 months. Exam-based certificates (such as WASSCE or GCE) need notarized or officially certified copies. A credit evaluation from WES or CED is needed only if you want credit from a non-US college.", "pg": "Send official sealed transcripts from every college attended, plus a course-by-course evaluation from a NACES agency showing a US bachelor's equivalent. You also need a resume, a personal statement and three recommendation letters. GRE or GMAT may be required depending on the program.", "english": "Required unless your degree was taught fully in English. Undergraduate: TOEFL 61 (tests before 1/21/26), IELTS 6, PTE 44, Duolingo 100. Graduate: TOEFL 79 (tests before 1/21/26), IELTS 6.5, PTE 53, Duolingo 110.", "how_to_apply": "Apply on the BSU online application or the Common Application. Graduate applicants apply online and upload other materials.", "deadlines": "Undergraduate: no dates listed, but BSU advises starting at least eight months early. Graduate rolling programs for F-1 applicants outside the US: Fall June 1, Spring November 1. Some programs have earlier deadlines.", "application_fee": "$50, paid online.", "documents": "Transcripts, English results, Affidavit of Financial Support and bank statement, passport copy valid six months. The I-20 is issued only after admission and all credentials. BSU estimates about $46,448 for a year of undergraduate costs.", "fees_link": "https://www.bridgew.edu/admissions/undergraduate-international-applicants", "sources": ["https://www.bridgew.edu/admissions/undergraduate-international-applicants", "https://www.bridgew.edu/graduate-international"]}$q$::jsonb, admission_link = $q$https://www.bridgew.edu/admissions/undergraduate-international-applicants$q$, admission_checked = '2026-11-13' where id = '3a56b278-c7d7-420d-b994-47345be24f28' and country = 'United States';
update schools set admission_info = $q${"ug": "Undergraduate applicants use the same application as domestic students. International applicants also need an English proficiency test (can be waived), proof of finances, and for transfers with foreign credit, a course-by-course evaluation with course descriptions. Official transcripts evaluated by a credential agency are required.", "pg": "Graduate programs have their own requirements, and tests such as GRE or GMAT apply where the program asks. Check your college or department. Official course-by-course evaluated transcripts are required.", "english": "Undergraduate: TOEFL iBT 61 or IELTS 5.0. Graduate: TOEFL iBT 71 or IELTS 6.0. TSU's TOEFL code is 1803. Completing the TSU Intensive English Center at the set level can replace test scores.", "how_to_apply": "Apply to TSU, send transcripts evaluated by a credential agency such as WES or ECE, complete the immunization form, give a financial guarantee, then receive the I-20 and accept your offer. Decisions can take 60 to 90 days.", "application_fee": "$35, non-refundable.", "documents": "Evidence of funds of at least $28,500 USD for the academic year plus an affidavit of support, passport copy, immunization form, official transcripts, and health insurance for F-1 students.", "fees_link": "https://www.tnstate.edu/international/requesti20.aspx", "sources": ["https://www.tnstate.edu/international/requesti20.aspx", "https://www.tnstate.edu/international/internationalstudent-FAQs.aspx", "https://www.tnstate.edu/policies/documents/UndergraduateLanguageEquivalency.pdf", "https://www.tnstate.edu/policies/documents/GraduateSchoolEnglishProficiency.pdf"]}$q$::jsonb, admission_link = $q$https://www.tnstate.edu/international/requesti20.aspx$q$, admission_checked = '2026-11-13' where id = '253c2ce8-039d-4545-80e2-5713defcaeb3' and country = 'United States';
update schools set admission_info = $q${"ug": "You need the US equivalent of a high school diploma and a course-by-course evaluation of your foreign transcripts from an approved evaluator (SpanTran TEC, ECE, ICD or another NACES member). Applicants from English-speaking countries who skip the English test must submit an SAT Evidence-Based Reading and Writing score of 560 or higher.", "pg": "You need the US equivalent of a four-year bachelor's degree shown on an evaluated transcript from SpanTran TEC, WES, ECE, ICD or another NACES member. Some programs also ask for a resume, statement of interest or essay.", "english": "Undergraduate: TOEFL 4 on the new iBT scale, IELTS 6.0 or Duolingo 95 (recommended scores). Graduate: IELTS 6.0 or Duolingo 95, with higher scores for some programs. The graduate TOEFL figure on the page looks unclear, so confirm it with the university. TOEFL code is 2657.", "how_to_apply": "Complete the online international application, pay the fee, send evaluated transcripts, English results and the Statement of Financial Support, then check status online.", "deadlines": "Applicants outside the US: Fall June 15, Spring November 1. Applicants in the US: Fall July 15, Spring November 15. Summer enrollment is not available to international students.", "application_fee": "$45 USD.", "documents": "Evaluated transcripts, English results, passport or ID scan, Statement of Financial Support from each sponsor and certified sponsor bank statements (F-1 applicants).", "fees_link": "https://www.ship.edu/admissions/international-students/international-applicants/", "sources": ["https://www.ship.edu/admissions/international-students/international-applicants/", "https://www.ship.edu/admissions/international-students/graduate-international-applicants/"]}$q$::jsonb, admission_link = $q$https://www.ship.edu/admissions/international-students/international-applicants/$q$, admission_checked = '2026-11-13' where id = '796a8c5e-1f64-4c12-a935-6fab72f8e115' and country = 'United States';
update schools set admission_info = $q${"ug": "First-year applicants need one of: ACT 21 or SAT 1060, a 2.25 cumulative GPA, or top 50% of class. Transfers need a 2.0 GPA and good standing. You need official transcripts (university transcripts must be evaluated by a recognized agency), a passport ID page and proof of finances such as a bank statement covering one year. AS and A-Level exams count as college credit with a minimum grade of C.", "english": "TOEFL iBT 68, IELTS 6.0 or Duolingo 95. iTEP, WAEC, CBSE or CISCE scores can also be used. A TOEFL writing score below 25 needs an on-campus placement exam.", "how_to_apply": "Apply online at admissions.mssu.edu. Contact info@mssu.edu or 866-818-6778.", "application_fee": "$60, non-refundable.", "documents": "Transcripts, passport ID page, English proof, and proof of finances. A $3,000 deposit is due after you get a visa.", "fees_link": "https://www.mssu.edu/admissions/files/26-27%20International%20Guide.pdf", "sources": ["https://www.mssu.edu/admissions/files/26-27%20International%20Guide.pdf", "https://www.mssu.edu/admissions/international-admissions.php"]}$q$::jsonb, admission_link = $q$https://www.mssu.edu/admissions/files/26-27%20International%20Guide.pdf$q$, admission_checked = '2026-11-13' where id = '311b8260-bdb9-485a-b28d-2c2c24510b7f' and country = 'United States';
update schools set admission_info = $q${"ug": "You must be a high-school graduate with about 12 years of schooling. Send official transcripts or certificates with English translation and an explanation of the grading system. Applicants under 22 must submit SAT or ACT scores. College work outside the US needs a course-by-course evaluation, and WES is recommended.", "pg": "You need a bachelor's degree. Send official transcripts with a course-by-course evaluation including GPA from a NACES company. Some programs ask for GRE or MAT, a resume, recommendation letters, a statement or an interview. Proof of measles and rubella immunity is needed if born after December 31, 1956.", "english": "Undergraduate: TOEFL iBT 61 (paper 500, computer 173) or IELTS 6.0. Graduate: TOEFL iBT 75, IELTS 6 or Duolingo 100, with scores less than two years old. Waivers apply for a degree taught in English or countries where English is the main official language.", "how_to_apply": "Apply online and apply at least six months before your start. After admission, request your I-20 with the Financial Certification form and pay the SEVIS fee.", "deadlines": "Undergraduate: Fall 2026 July 1, Spring 2027 November 1. Graduate deadlines are not listed.", "application_fee": "$100 for international applicants, non-refundable.", "documents": "Transcripts, English results, credential evaluation if you studied at a non-US college, proof of funds for one year, Financial Certification form, I-20 request form, immunization records and health insurance.", "fees_link": "https://uscupstate.edu/admissions/international-students/", "sources": ["https://uscupstate.edu/admissions/international-students/", "https://academic-catalog.uscupstate.edu/graduate-programs/admission"]}$q$::jsonb, admission_link = $q$https://uscupstate.edu/admissions/international-students/$q$, admission_checked = '2026-11-13' where id = '30b9a6e6-ce3b-4cbf-824b-4b539f215584' and country = 'United States';
